        require(address(this).balance >= fundAmount);

        c.Command{value: fundAmount}(address(this), ""); if (__ESBMC_reverted()) return;

        uint256 balBefore = address(c).balance;

        bool reverted = false;
        c.withdraw(); bool __rev0 = __ESBMC_reverted(); if (__rev0) {
