        fundAmount = bound(fundAmount, 0, 1000000000000000000000000000000);
        vm.deal(address(this), VALUE_CAP);
        vm.deal(address(c), VALUE_CAP);
        vm.assume(fundAmount > 0);
        vm.assume(address(this).balance >= fundAmount);
        try c.Command{value: fundAmount}(address(this), "") {} catch { return; }
        uint256 balBefore = address(c).balance;
        bool reverted = false;
        try c.withdraw() {
            reverted = false;
        } catch {
            reverted = true;
        }
        assertTrue(!reverted && address(c).balance == 0);
    }

    function testFuzz_run(uint256 fundAmount) public {
        _run(fundAmount);
